function F({registerIndicator:x,sourceValues:M,nulls:f}){const m=(t,e)=>{const a=new Array(t.length).fill(NaN),n=new Array(e).fill(NaN);let r=0,i=0,s=0;for(let c=0;c<t.length;c++){const b=n[r];Number.isFinite(b)?i-=b:s+=1;const p=Number.isFinite(t[c])?t[c]:0;i+=p,n[r]=p,r=(r+1)%e,a[c]=i/Math.max(1,s)}return a},u=(t,e)=>{const a=new Array(t.length).fill(0);for(let n=0;n<t.length;n++){const r=Number.isFinite(t[n])?t[n]:0,i=n-e>=0?t[n-e]:NaN,s=Number.isFinite(i)?i:0;a[n]=s!==0?100*(r-s)/s:0}return a},l=(t,e)=>Math.min(500,Math.max(1,Math.floor(Number(t)||e)));x({id:"oa-kst",name:"KST Oscillator (KST)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"r1",type:"number",label:"ROC Period 1",default:10,min:1,max:500,step:1,tooltip:"Shortest ROC lookback."},{key:"r2",type:"number",label:"ROC Period 2",default:15,min:1,max:500,step:1},{key:"r3",type:"number",label:"ROC Period 3",default:20,min:1,max:500,step:1},{key:"r4",type:"number",label:"ROC Period 4",default:30,min:1,max:500,step:1,tooltip:"Longest ROC lookback."},{key:"s1",type:"number",label:"SMA Smooth 1",default:10,min:1,max:500,step:1},{key:"s2",type:"number",label:"SMA Smooth 2",default:10,min:1,max:500,step:1},{key:"s3",type:"number",label:"SMA Smooth 3",default:10,min:1,max:500,step:1},{key:"s4",type:"number",label:"SMA Smooth 4",default:15,min:1,max:500,step:1},{key:"signalPeriod",type:"number",label:"Signal Period",default:9,min:1,max:500,step:1,tooltip:"SMA period for the signal line."}],plots:[{key:"kst",type:"line",title:"KST",style:{color:"#ffeb3b",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#00bcd4",lineWidth:1}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(t,e){const a=l(e.r1,10),n=l(e.r2,15),r=l(e.r3,20),i=l(e.r4,30),s=l(e.s1,10),c=l(e.s2,10),b=l(e.s3,10),p=l(e.s4,15),g=l(e.signalPeriod,9),y=M(t,e.source??"close"),k=m(u(y,a),s),h=m(u(y,n),c),N=m(u(y,r),b),S=m(u(y,i),p),d=new Array(t.length).fill(NaN);for(let o=0;o<t.length;o++)!Number.isFinite(k[o])||!Number.isFinite(h[o])||!Number.isFinite(N[o])||!Number.isFinite(S[o])||(d[o]=1*k[o]+2*h[o]+3*N[o]+4*S[o]);const A=m(d,g);return{kst:f(d),signal:f(A)}}})}export{F as default};
